<script lang="ts">
  import { onMount } from 'svelte'; import { Button } from 'm3-svelte';
  import { api, errorMessage, type Service } from '$lib/api';
  let services: Service[] = []; let service = ''; let client = 'opencode'; let majorVersion = ''; let key = ''; let config = ''; let result = ''; let error = ''; let busy = false; let loading = true;
  onMount(async () => { try { services = (await api.services()).services; } catch (e) { error = errorMessage(e); } finally { loading = false; } });
  async function generate() { busy = true; error = ''; config = ''; result = ''; try { config = (await api.clientConfig({ service, client, major_version: majorVersion })).config; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function check() { busy = true; error = ''; result = ''; try { const response = await api.checkClient({ service, client, major_version: majorVersion, key }); result = `${response.ok ? 'Passed' : 'Failed'}: ${response.detail}`; } catch (e) { error = errorMessage(e); } finally { key = ''; busy = false; } }
</script>
<div class="page"><div class="heading"><div><h1>Client setup</h1><p class="subtitle">Generate configuration from a published service's validated contract.</p></div></div>{#if error}<div class="error" role="alert">{error}</div>{/if}
<form class="panel form stack" onsubmit={(event) => { event.preventDefault(); generate(); }}><label>Service<select required bind:value={service}><option value="" disabled>Select a service</option>{#each services as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Client<select bind:value={client}><option value="opencode">opencode</option><option value="pi">pi</option><option value="claude-code">Claude Code</option><option value="codex">Codex</option></select></label><label>Client major version<input required bind:value={majorVersion} /></label><div><Button type="submit" disabled={busy || loading}>Generate configuration</Button></div></form>
{#if config}<section class="section"><h2>Configuration</h2><p class="muted">Stored keys cannot be retrieved; replace any key placeholder with a key you control.</p><pre>{config}</pre></section>{/if}
<section class="section"><h2>Check your setup</h2><p class="muted">Run a tool-call round trip using a key you paste. The key is cleared from this form after the request.</p><form class="panel form stack" onsubmit={(event) => { event.preventDefault(); check(); }}><label>API key<input type="password" autocomplete="off" required bind:value={key} /></label><div><Button type="submit" variant="outlined" disabled={busy || !service || !majorVersion}>Check setup</Button></div></form>{#if result}<p role="status">{result}</p>{/if}</section></div>
